--
-- 傾印資料表的資料 `track_results`
--


--
-- 觸發器 `track_results`
--
DELIMITER $$
CREATE TRIGGER `sync_to_hall_of_fame` AFTER INSERT ON `track_results` FOR EACH ROW BEGIN
    VALUES (NEW.user_id, NEW.track_id, NEW.time_ms, NEW.created_at)
    ON DUPLICATE KEY UPDATE 
    time_ms = IF(NEW.time_ms < track_log.time_ms, NEW.time_ms, track_log.time_ms),
    created_at = IF(NEW.time_ms < track_log.time_ms, NEW.created_at, track_log.created_at);
END
$$
DELIMITER ;

