DELIMITER $$
--
-- 事件
--
CREATE DEFINER=`root`@`localhost` EVENT `auto_approve_custom_tracks` ON SCHEDULE EVERY 2 MINUTE STARTS '2026-07-03 02:24:02' ON COMPLETION PRESERVE ENABLE COMMENT '每2分鐘自動將自訂路線 pending 改為 approved' DO BEGIN
    UPDATE custom_tracks 
    SET status = 'approved', 
        is_hidden = 0,
        approved_at = NOW()
    WHERE status = 'pending';
END$$

