INSERT INTO `announcements` (`id`, `title`, `content`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
(2, '🏁 REV-ON｜系統更新公告', '🔥 全新功能搶先公開\r\n\r\n🚗 車種選擇\r\n選擇你的車種，建立專屬的車手資訊。\r\n\r\n🛣️ 新增路線\r\n自己建立想挑戰的路線，打造專屬賽道！\r\n\r\n📖 功能導覽\r\n新手也能快速上手，帶你了解 APP 各項功能。\r\n\r\n📝 問題回報功能\r\n遇到問題可直接回報，儘快快協助處理！\r\n\r\n📌 重要提醒： \r\n▪舊用戶目前可自行編輯 Email  \r\n▪ 新註冊用戶將強制綁定 Email  \r\n\r\n請大家務必確認 Email 是否填寫正確！  \r\n\r\n⚠ 若 Email 填寫錯誤，可能會導致： \r\n・忘記密碼時無法找回帳號  \r\n・無法正常訂閱 VIP 功能  \r\n\r\n 📱 全新 APP｜即將上架\r\n目前持續優化與測試中，\r\n更多新功能也將陸續公開！\r\n\r\n 感謝大家的支持 ❤️', 1, 2112, '2026-08-10 19:54:08', '2026-08-10 19:54:08');
